import json, os, socket, subprocess, time
from pathlib import Path
out=Path("artifacts/evaluacion-modelos-llamacode/Q-20261024-VF-ITERATION-97/receipts/q97-host-preflight.json")
def run(args):
    p=subprocess.run(args,capture_output=True,text=True,timeout=20)
    return {"returnCode":p.returncode,"stdout":p.stdout.strip(),"stderr":p.stderr.strip()}
def parse_psi():
    vals={}
    for line in Path("/proc/pressure/memory").read_text().splitlines():
        bits=line.split()
        if bits[0] in ("some","full"):
            vals[bits[0]]={k:float(v) for k,v in (x.split("=") for x in bits[1:] if x.startswith("avg10="))}
            if "avg10" in vals[bits[0]]: vals[bits[0]]["avg10"]=vals[bits[0]].pop("avg10")
    return vals
def proc_inference():
    found=[]
    patterns=("llama-server","llama_server","vllm","serve/server.py","strata")
    me=os.getpid()
    for p in Path("/proc").iterdir():
        if not p.name.isdigit() or int(p.name)==me: continue
        try:
            raw=(p/"cmdline").read_bytes().split(b"\0")
            argv=[x.decode(errors="replace") for x in raw if x]
            if not argv: continue
            base=Path(argv[0]).name.lower()
            full=" ".join(argv).lower()
            if base in ("llama-server","llama-server.exe","vllm") or any(s in full for s in patterns):
                found.append({"pid":int(p.name),"comm":Path("/proc/"+p.name+"/comm").read_text().strip(),"cmdline":argv})
        except (OSError,PermissionError):
            continue
    return found
gpu=run(["nvidia-smi","--query-gpu=index,name,uuid,memory.used,memory.total","--format=csv,noheader,nounits"])
apps=run(["nvidia-smi","--query-compute-apps=gpu_uuid,pid,process_name,used_memory","--format=csv,noheader,nounits"])
listeners={}
for port in (8363,18789):
    s=socket.socket(); s.settimeout(.5)
    try: listeners[str(port)]=(s.connect_ex(("127.0.0.1",port))==0)
    finally: s.close()
mem={}
for line in Path("/proc/meminfo").read_text().splitlines():
    if line.startswith("MemAvailable:"): mem["memAvailableGiB"]=round(int(line.split()[1])*1024/1024**3,3)
vm={}
for line in Path("/proc/vmstat").read_text().splitlines():
    if line.split()[0] in ("oom_kill","oom_kill_process"): vm[line.split()[0]]=int(line.split()[1])
procs=proc_inference()
