gpu_ok=gpu["returnCode"]==0 and len(gpu_lines)==2 and all("3090" in x.lower() for x in gpu_lines)
psi=parse_psi()
psi_ok=all(psi.get(k,{}).get("avg10",999)<5.0 for k in ("some","full"))
passed=gpu_ok and not procs and not any(listeners.values()) and mem.get("memAvailableGiB",0)>=32 and psi_ok
result={
 "taskId":"Q-20261024-VF-ITERATION-97",
 "checkedAtUtc":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime()),
 "gpuQuery":gpu,"gpuComputeApps":apps,"gpuTopologyConfirmed":gpu_ok,
 "inferenceProcesses":procs,"candidatePortsListening":listeners,
 "memory":mem,"memoryPsiAvg10Pct":psi,"oomCounters":vm,
 "preflightPassed":passed,
 "decision":"PASS; no external inference process/listener, both RTX 3090 visible, memory and baseline PSI gates pass." if passed else "BLOCK; inspect failed preflight fields before starting any model.",
 "desktopModified":False,"modelLoaded":False,"requestSent":False
}
out.write_text(json.dumps(result,ensure_ascii=False,indent=2)+"\n")
print(json.dumps(result,ensure_ascii=False,indent=2))
